import java.util.Scanner;

public class Main {
    static final int MAX_SIZE = 31;
    static final long MOD = 1000000007;

    static class Matrix {
        long[][] m;
        int N;

        public Matrix(int N) {
            this.N = N;
            m = new long[N][N];
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    m[i][j] = 0;
                }
            }
            for (int i = 0; i < N; i++) {
                m[i][i] = 1;
            }
        }

        public Matrix multiply(Matrix b) {
            Matrix ret = new Matrix(N);
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    long cans = 0;
                    for (int k = 0; k < N; k++) {
                        cans += this.m[i][k] * b.m[k][j];
                        cans %= MOD;
                    }
                    ret.m[i][j] = cans;
                }
            }
            return ret;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        int k = sc.nextInt();

        Matrix[][] M = new Matrix[71][31];

        for (int i = 0; i < k; i++) {
            M[0][i] = new Matrix(k + 1);
            for (int j = 0; j <= k; j++) {
                M[0][i].m[i][j] = 1;
            }
        }

        long[] kp = new long[100];
        kp[0] = 1;
        kp[1] = k;
        int lg = 2;
        while (kp[lg - 1] <= n / k) {
            kp[lg] = kp[lg - 1] * k;
            lg++;
        }

        for (int i = 1; i < lg; i++) {
            M[i][0] = new Matrix(k + 1);
            for (int j = 1; j < k; j++) {
                M[i][j] = M[i - 1][j - 1].multiply(M[i][j - 1]);
            }
            Matrix cpro = new Matrix(k + 1);
            for (int j = k - 1; j >= 0; j--) {
                cpro = cpro.multiply(M[i - 1][j]);
                M[i][j] = M[i][j].multiply(cpro);
            }
        }

        Matrix ans = new Matrix(k + 1);
        int cc = 0;
        for (int i = lg - 1; i >= 0; i--) {
            while (kp[i] <= n) {
                n -= kp[i];
                ans = M[i][cc].multiply(ans);
                cc++;
                cc %= k;
            }
        }

        long ret = 0;
        for (int i = 0; i <= k; i++) {
            ret += ans.m[i][k];
            ret %= MOD;
        }
        System.out.println(ret);
        sc.close();
    }
}
